from pathlib import Path
class FileCache:
    def __init__(self): self.entries={}
    def read(self,path):
        path=Path(path); stat=path.stat();key=(stat.st_size,stat.st_mtime_ns)
        if path not in self.entries or self.entries[path][0]!=key: self.entries[path]=(key,path.read_text())
        return self.entries[path][1]

